args.command:
tail -1 /root/.nanobot/request_logs/2026-05-15.jsonl | python3 -c "
import json, sys
r = json.loads(sys.stdin.read())
msgs = r.get('messages', [])
# Check the LAST 5 messages for cache_control
for i in range(max(0, len(msgs)-5), len(msgs)):
    m = msgs[i]
    role = m.get('role', '?')
    content = m.get('content', '')
    if isinstance(content, list):
        has_cc = any(isinstance(c, dict) and c.get('cache_control') for c in content)
        print(f'[{i}] role={role} type=list cache_control={has_cc}')
        for c in content:
            if isinstance(c, dict) and c.get('cache_control'):
                print(f'    CC block: {c.get(\"text\",\"\")[:100]}')
    elif isinstance(content, str):
        print(f'[{i}] role={role} type=str len={len(content)} preview={content[:100]}')
    else:
        print(f'[{i}] role={role} type={type(content).__name__}')
"

args.old_text:
    supports_prompt_caching=True,
),
